CREATE OR REPLACE VIEW `vwenasarcoanno` AS select `i`.`fornitore` AS `fornitore`,`i`.`competenza` AS `competenza`,`f`.`enasarco` AS `enasarco`,sum(`i`.`total_amount`) AS `fatturato` from ((`invoices` `i` join `fornitoris` `f` on((`i`.`fornitori_id` = `f`.`id`))) left join `enasarcos` `e` on(((`f`.`enasarco` = `e`.`enasarco`) and (`i`.`competenza` = `e`.`competenza`)))) group by `i`.`fornitore`,`i`.`competenza`,`f`.`enasarco` order by `i`.`fornitore`
